package com.hs.jxc.workflow.service;

import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.service.*;
import com.hs.jxc.workflow.api.WorkflowApi;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;

/** Governed, same-transaction prerequisite. Business submission routes remain closed in M1. */
@Service
public class WorkflowService implements WorkflowApi {
    private final DocumentGovernanceService governance;private final com.hs.jxc.common.audit.AuditWriter auditWriter;private final JdbcTemplate jdbc;private final AuthorizationService auth;private final DocumentAccessService docs;private final SystemManagementService management;private final FieldPolicyService fields;private final JsonCodec json;private final TransactionTemplate tx;
    private final Map<String,Set<String>> critical=new ConcurrentHashMap<>();
    private final Map<String,com.hs.jxc.workflow.api.WorkflowParticipant> participants=new ConcurrentHashMap<>();
    @Override public void registerParticipant(String type,com.hs.jxc.workflow.api.WorkflowParticipant participant){
        if(participants.putIfAbsent(type,Objects.requireNonNull(participant))!=null)throw new IllegalStateException("Duplicate workflow participant: "+type);
    }
    public WorkflowService(JdbcTemplate jdbc,AuthorizationService auth,DocumentAccessService docs,SystemManagementService management,FieldPolicyService fields,JsonCodec json,PlatformTransactionManager tm,com.hs.jxc.common.audit.AuditWriter auditWriter,DocumentGovernanceService governance){this.governance=governance;this.auditWriter=auditWriter;this.jdbc=jdbc;this.auth=auth;this.docs=docs;this.management=management;this.fields=fields;this.json=json;this.tx=new TransactionTemplate(tm);
        for(String type:List.of("ORG_ENTITY","ENTITY"))critical.put(type,Set.of("name","status"));
        for(String type:List.of("ORG_STORE","STORE"))critical.put(type,Set.of("name","entityId","status"));
        for(String type:List.of("ORG_WAREHOUSE","WAREHOUSE"))critical.put(type,Set.of("name","entityId","storeId","status"));
        for(String type:List.of("FIN_BOOK","BOOK"))critical.put(type,Set.of("name","entityId","baseCurrency","status"));
    }
    public void registerCriticalFields(String type,Set<String> required){if(required.isEmpty()||critical.putIfAbsent(type,Set.copyOf(required))!=null)throw new IllegalStateException("Invalid or duplicate workflow document policy");}
    private Access actor(RequestContext c){return auth.authorize(c);}
    private <T>T ruleWrite(RequestContext c,Function<Access,T> work){return tx.execute(s->{var a=auth.authorizePolicyWrite(c,false);ruleAdmin(a);T out=work.apply(a);auth.bump(a.requireCountry());return out;});}
    private void ruleAdmin(Access a){a.requireCountry();a.require("wf:rule:edit");if(!a.scope().all())throw new ApiException(403,"SYS_FORBIDDEN","国家级审批规则需本国全部数据范围");}
    @Override public Map<String,Object> submit(RequestContext c,String type,long id,Map<String,Object> facts,boolean forceRequired){
        requireTransaction();Access a=actor(c);var source=docs.requireLockedDocumentAccess(a,type,id,true);requireCritical(type);
        var cfg=config(a,type);boolean required=forceRequired||cfg==null||Boolean.TRUE.equals(cfg.get("approval_required"));
        Map<String,Object> authoritativeFacts=new HashMap<>(facts==null?Map.of():facts);authoritativeFacts.putAll(source);
        var candidates=jdbc.queryForList("SELECT * FROM wf_rule WHERE country_id=? AND doc_type=? AND status='ACTIVE' AND effective_from<=clock_timestamp() AND (effective_to IS NULL OR effective_to>clock_timestamp()) ORDER BY priority,id",a.requireCountry(),type);
        var rule=candidates.stream().filter(r->matches(list(r.get("conditions")),authoritativeFacts)).findFirst().orElse(null);
        Map<String,Object> selected=snapshot(type,source,cfg);
        Map<String,Object> saved=new LinkedHashMap<>();saved.put("fields",selected);saved.put("facts",authoritativeFacts);saved.put("docNo",source.getOrDefault("docNo",source.getOrDefault("code",String.valueOf(id))));saved.put("docTitle",source.getOrDefault("docTitle",source.getOrDefault("name",type)));
        String status;String reason=null;List<Map<String,Object>> nodes=rule==null?List.of():list(rule.get("nodes"));List<Long> first=List.of();
        if(rule==null){status=required?"BLOCKED":"APPROVED";if(required)reason="没有匹配的审批规则";}
        else if(nodes.isEmpty()){status="BLOCKED";reason="审批规则没有有效节点";}
        else {status="PENDING";for(var node:nodes){var eligible=approvers(a,node,type,id);if(eligible.isEmpty()){status="BLOCKED";reason="节点“"+node.get("nodeName")+"”没有可用审批人";break;}if(first.isEmpty())first=eligible;}}
        Long instance=jdbc.queryForObject("INSERT INTO wf_instance(country_id,doc_type,doc_id,doc_version,rule_id,rule_version_no,key_fields_hash,key_fields_snapshot,approval_required,status,submitted_by,blocked_reason,finished_at) VALUES(?,?,?,?,?,?,?,?::jsonb,?,?,?,?,CASE WHEN ?='APPROVED' THEN clock_timestamp() ELSE NULL END) RETURNING id",Long.class,a.requireCountry(),type,id,source.getOrDefault("version",1),rule==null?null:rule.get("id"),rule==null?0:rule.get("version_no"),hash(selected),json.write(saved),required,status,a.userId(),reason,status);
        if(status.equals("PENDING"))createTasks(a,instance,nodes.getFirst(),first);
        if(status.equals("BLOCKED"))todo(a,type,id,reason);else jdbc.update("UPDATE sys_todo SET status='DONE',resolved_at=clock_timestamp(),version=version+1 WHERE country_id=? AND dedup_key=? AND status='OPEN'",a.requireCountry(),"WF_BLOCKED:"+type+":"+id);
        governance.notifyCc(a,type,id,source);
        audit(a,"提交审批",instance,Map.of("docType",type,"docId",id,"status",status));
        return Map.of("status",status,"instanceId",instance,"message",reason==null?(status.equals("APPROVED")?"单据类型明确无需审批":"已提交审批"):reason);
    }
    @Override public void requireApproved(RequestContext c,String type,long id){requireTransaction();var a=actor(c);var source=docs.requireLockedDocumentAccess(a,type,id,false);var rows=jdbc.queryForList("SELECT * FROM wf_instance WHERE country_id=? AND doc_type=? AND doc_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE",a.requireCountry(),type,id);if(rows.isEmpty())throw new ApiException(400,"WF_APPROVAL_REQUIRED","请先提交审批");var inst=rows.getFirst();if(!"APPROVED".equals(inst.get("status")))throw new ApiException(409,"INVALIDATED".equals(inst.get("status"))?"WF_APPROVAL_INVALIDATED":"WF_APPROVAL_REQUIRED","单据尚无有效审批");if(!snapshotMatches(inst,source))throw invalidated();}
    @Override public void invalidate(RequestContext c,String type,long id,String reason){requireTransaction();var a=actor(c);prepareParticipant(c,a,type,id);docs.requireLockedDocumentAccess(a,type,id,true);int changed=jdbc.update("UPDATE wf_instance SET status='INVALIDATED',blocked_reason=?,version=version+1 WHERE country_id=? AND doc_type=? AND doc_id=? AND status='APPROVED'",reason,a.requireCountry(),type,id);if(changed>0)decision(c,a,type,id,"INVALIDATED");audit(a,"审批失效",id,Map.of("docType",type,"reason",reason));}
    public Map<String,Object> createRule(RequestContext c,Map<String,Object>b){return ruleWrite(c,a->{validateRule(a,b);String key="R-"+UUID.randomUUID();Long id=insertRule(a,b,key,1,"ACTIVE");audit(a,"新增审批规则",id,Map.of("ruleKey",key,"versionNo",1));return ruleOut(rule(a,id,false));});}
    public Map<String,Object> updateRule(RequestContext c,long id,Map<String,Object>b){return ruleWrite(c,a->{var old=rule(a,id,true);if(((Number)old.get("version")).longValue()!=Inputs.version(b))throw Inputs.conflict();if("RETIRED".equals(old.get("status")))throw state("历史规则版本不能修改");validateRule(a,b);int number=((Number)old.get("version_no")).intValue()+1;Long next=insertRule(a,b,String.valueOf(old.get("rule_key")),number,String.valueOf(old.get("status")));jdbc.update("UPDATE wf_rule SET status='RETIRED',version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND id=?",a.requireCountry(),id);audit(a,"审批规则新版本",next,Map.of("previousId",id,"versionNo",number));var out=ruleOut(rule(a,next,false));out.put("inflight",jdbc.queryForObject("SELECT count(*) FROM wf_instance WHERE country_id=? AND rule_id=? AND status='PENDING'",Integer.class,a.requireCountry(),id));return out;});}
    public Map<String,Object> toggleRule(RequestContext c,long id,boolean active){return ruleWrite(c,a->{var old=rule(a,id,true);if("RETIRED".equals(old.get("status")))throw state("历史规则版本不能启停");if(active)validateRule(a,ruleOut(old));jdbc.update("UPDATE wf_rule SET status=?,version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND id=?",active?"ACTIVE":"DISABLED",a.requireCountry(),id);audit(a,active?"启用审批规则":"停用审批规则",id,Map.of("status",active?"ACTIVE":"DISABLED"));return ruleOut(rule(a,id,false));});}
    public Map<String,Object> rules(RequestContext c,Map<String,String> q){return tx.execute(s->{var a=actor(c);ruleAdmin(a);var rows=jdbc.queryForList("SELECT * FROM wf_rule WHERE country_id=? ORDER BY doc_type,priority,id",a.requireCountry()).stream().filter(r->q.getOrDefault("status","").isEmpty()?!"RETIRED".equals(r.get("status")):q.get("status").equals(r.get("status"))).filter(r->q.getOrDefault("docType","").isEmpty()||q.get("docType").equals(r.get("doc_type"))).map(this::ruleOut).toList();return page(rows,q);});}
    public Map<String,Object> getRule(RequestContext c,long id){return tx.execute(s->{var a=actor(c);ruleAdmin(a);return ruleOut(rule(a,id,false));});}
    public List<Map<String,Object>> versions(RequestContext c,long id){return tx.execute(s->{var a=actor(c);ruleAdmin(a);var current=rule(a,id,false);return jdbc.queryForList("SELECT * FROM wf_rule WHERE country_id=? AND rule_key=? ORDER BY version_no DESC",a.requireCountry(),current.get("rule_key")).stream().map(r->{var out=ruleOut(r);out.put("instanceCount",jdbc.queryForObject("SELECT count(*) FROM wf_instance WHERE country_id=? AND rule_id=?",Integer.class,a.requireCountry(),r.get("id")));return out;}).toList();});}
    public List<Map<String,Object>> docTypes(RequestContext c){return tx.execute(s->{var a=actor(c);ruleAdmin(a);return jdbc.queryForList("SELECT * FROM wf_doc_type_config WHERE country_id=? ORDER BY doc_type",a.requireCountry()).stream().map(r->{var out=camel(r);out.put("keyFields",json.read(String.valueOf(r.get("key_fields")),List.class));return out;}).toList();});}
    public Map<String,Object> configure(RequestContext c,String type,Map<String,Object>b){return ruleWrite(c,a->{var old=config(a,type);if(old!=null&&((Number)old.get("version")).longValue()!=Inputs.version(b))throw Inputs.conflict();if(!(b.get("approvalRequired") instanceof Boolean))throw Inputs.bad("审批开关必须为布尔值");List<String> keys=SystemManagementService.strings(b.get("keyFields"));for(String key:keys)if(!key.matches("[A-Za-z][A-Za-z0-9]*"))throw Inputs.bad("关键字段不合法");jdbc.update("INSERT INTO wf_doc_type_config(country_id,doc_type,approval_required,key_fields) VALUES(?,?,?,?::jsonb) ON CONFLICT(country_id,doc_type) DO UPDATE SET approval_required=EXCLUDED.approval_required,key_fields=EXCLUDED.key_fields,version=wf_doc_type_config.version+1",a.requireCountry(),type,b.get("approvalRequired"),json.write(keys));var stored=config(a,type);audit(a,"修改单据审批设置",((Number)stored.get("id")).longValue(),Map.of("docType",type,"approvalRequired",b.get("approvalRequired")));var result=camel(stored);result.put("keyFields",keys);return result;});}
    public Map<String,Object> approve(RequestContext c,long taskId,String comment){return act(c,taskId,comment,true);}
    public Map<String,Object> reject(RequestContext c,long taskId,String comment){if(comment==null||comment.isBlank())throw Inputs.bad("驳回时必须填写意见");return act(c,taskId,comment,false);}
    private Map<String,Object> act(RequestContext c,long taskId,String comment,boolean approve){var result=tx.execute(s->{var a=actor(c);var hints=jdbc.queryForList("SELECT i.doc_type,i.doc_id,i.id instance_id FROM wf_task t JOIN wf_instance i ON i.country_id=t.country_id AND i.id=t.instance_id WHERE t.country_id=? AND t.id=? AND "+DocumentGovernanceService.taskVisibility(),a.requireCountry(),taskId,a.userId(),a.userId());if(hints.isEmpty())throw missing();var hint=hints.getFirst();String type=String.valueOf(hint.get("doc_type"));long docId=((Number)hint.get("doc_id")).longValue();prepareParticipant(c,a,type,docId);var source=docs.requireLockedDocumentAccess(a,type,docId,false);var inst=jdbc.queryForMap("SELECT * FROM wf_instance WHERE country_id=? AND id=? FOR UPDATE",a.requireCountry(),hint.get("instance_id"));var task=jdbc.queryForMap("SELECT * FROM wf_task WHERE country_id=? AND id=? FOR UPDATE",a.requireCountry(),taskId);governance.requireTaskAuthority(a,task,type,docId);if(!"PENDING".equals(task.get("status"))||!"PENDING".equals(inst.get("status")))throw state("这条审批已处理");
        if(!snapshotMatches(inst,source)){jdbc.update("UPDATE wf_instance SET status='INVALIDATED',blocked_reason='关键字段已改变',version=version+1 WHERE country_id=? AND id=?",a.requireCountry(),inst.get("id"));skip(a,inst);decision(c,a,type,docId,"INVALIDATED");audit(a,"审批失效",((Number)inst.get("id")).longValue(),Map.of("taskId",taskId));return Map.<String,Object>of("invalidated",true);}
        jdbc.update("UPDATE wf_task SET status=?,comment=?,acted_at=clock_timestamp(),acted_by=?,delegate_from_id=CASE WHEN assignee_id<>? THEN assignee_id ELSE NULL END,version=version+1 WHERE country_id=? AND id=?",approve?"APPROVED":"REJECTED",comment==null?"":comment,a.userId(),a.userId(),a.requireCountry(),taskId);
        if(!approve){skip(a,inst);finish(a,inst,"REJECTED");}
        else {var rule=rule(a,((Number)inst.get("rule_id")).longValue(),false);var nodes=list(rule.get("nodes"));int seq=((Number)task.get("node_seq")).intValue();var node=nodes.stream().filter(n->((Number)n.get("seq")).intValue()==seq).findFirst().orElseThrow(()->state("审批规则快照缺失"));int pending=jdbc.queryForObject("SELECT count(*) FROM wf_task WHERE country_id=? AND instance_id=? AND node_seq=? AND status='PENDING'",Integer.class,a.requireCountry(),inst.get("id"),seq);
            if(!"ALL".equals(node.get("mode"))||pending==0){skipNode(a,inst,seq);var next=nodes.stream().filter(n->((Number)n.get("seq")).intValue()==seq+1).findFirst().orElse(null);if(next==null)finish(a,inst,"APPROVED");else{var eligible=approvers(a,next,type,docId);if(eligible.isEmpty()){jdbc.update("UPDATE wf_instance SET status='BLOCKED',blocked_reason='下一节点没有可用审批人',version=version+1 WHERE country_id=? AND id=?",a.requireCountry(),inst.get("id"));todo(a,type,docId,"下一节点没有可用审批人");}else createTasks(a,((Number)inst.get("id")).longValue(),next,eligible);}}}
        String decided=jdbc.queryForObject("SELECT status FROM wf_instance WHERE country_id=? AND id=?",String.class,a.requireCountry(),inst.get("id"));if(Set.of("APPROVED","REJECTED").contains(decided))decision(c,a,type,docId,decided);
        audit(a,approve?"审批通过":"审批驳回",((Number)inst.get("id")).longValue(),Map.of("taskId",taskId));return taskView(a,jdbc.queryForMap("SELECT t.*,i.doc_type,i.doc_id,i.status instance_status,i.key_fields_snapshot,i.rule_id,i.rule_version_no,i.submitted_by,i.submitted_at,r.name rule_name FROM wf_task t JOIN wf_instance i ON i.country_id=t.country_id AND i.id=t.instance_id LEFT JOIN wf_rule r ON r.country_id=i.country_id AND r.id=i.rule_id WHERE t.country_id=? AND t.id=?",a.requireCountry(),taskId));});if(Boolean.TRUE.equals(result.get("invalidated")))throw invalidated();return result;}
    public Map<String,Object> tasks(RequestContext c,Map<String,String> q){return tx.execute(s->{var a=actor(c);a.requireCountry();boolean done="done".equals(q.get("mode"));List<Map<String,Object>> out=new ArrayList<>();for(var row:jdbc.queryForList("SELECT t.*,i.doc_type,i.doc_id,i.status instance_status,i.key_fields_snapshot,i.rule_id,i.rule_version_no,i.submitted_by,i.submitted_at,r.name rule_name FROM wf_task t JOIN wf_instance i ON i.country_id=t.country_id AND i.id=t.instance_id LEFT JOIN wf_rule r ON r.country_id=i.country_id AND r.id=i.rule_id WHERE t.country_id=? AND "+DocumentGovernanceService.taskVisibility()+" ORDER BY t.id DESC",a.requireCountry(),a.userId(),a.userId())){if(done?Set.of("PENDING","SKIPPED").contains(row.get("status")):!"PENDING".equals(row.get("status"))||!"PENDING".equals(row.get("instance_status")))continue;try{governance.requireTaskAuthority(a,row,String.valueOf(row.get("doc_type")),((Number)row.get("doc_id")).longValue());docs.requireDocumentAccess(a,String.valueOf(row.get("doc_type")),((Number)row.get("doc_id")).longValue(),false);out.add(taskView(a,row));}catch(ApiException e){if(e.getStatus()!=403&&e.getStatus()!=404)throw e;}}return page(out,q);});}
    public List<Map<String,Object>> instances(RequestContext c,String type,long id){return tx.execute(s->{var a=actor(c);docs.requireDocumentAccess(a,type,id,false);return jdbc.queryForList("SELECT * FROM wf_instance WHERE country_id=? AND doc_type=? AND doc_id=? ORDER BY id DESC",a.requireCountry(),type,id).stream().map(r->{var out=camel(r);out.remove("keyFieldsSnapshot");out.remove("keyFieldsHash");out.put("submittedByName",historyUser(a,r.get("submitted_by")));if(r.get("rule_id")!=null){var names=jdbc.queryForList("SELECT name FROM wf_rule WHERE country_id=? AND id=?",String.class,a.requireCountry(),r.get("rule_id"));out.put("ruleName",names.isEmpty()?"":names.getFirst());}out.put("tasks",jdbc.queryForList("SELECT id,node_seq,node_name,assignee_id,status,comment,acted_at FROM wf_task WHERE country_id=? AND instance_id=? ORDER BY node_seq,id",a.requireCountry(),r.get("id")).stream().map(row->{var task=camel(row);task.put("assigneeName",historyUser(a,row.get("assignee_id")));return task;}).toList());return fields.mask(a,out,"ORDER_TOTAL");}).toList();});}
    /** Source access was checked before history labels; disabled historic actors remain identifiable. */
    private String historyUser(Access a,Object id){if(id==null)return "";var names=jdbc.queryForList("SELECT u.display_name FROM sys_user u WHERE u.id=? AND EXISTS(SELECT 1 FROM sys_user_role r WHERE r.user_id=u.id AND r.country_id=?)",String.class,id,a.requireCountry());return names.isEmpty()?"用户 #"+id:names.getFirst();}
    public Map<String,Object> withdraw(RequestContext c,long id){return tx.execute(s->{var a=actor(c);var hints=jdbc.queryForList("SELECT * FROM wf_instance WHERE country_id=? AND id=?",a.requireCountry(),id);if(hints.isEmpty())throw missing();var hint=hints.getFirst();prepareParticipant(c,a,String.valueOf(hint.get("doc_type")),((Number)hint.get("doc_id")).longValue());docs.requireLockedDocumentAccess(a,String.valueOf(hint.get("doc_type")),((Number)hint.get("doc_id")).longValue(),true);var inst=jdbc.queryForMap("SELECT * FROM wf_instance WHERE country_id=? AND id=? FOR UPDATE",a.requireCountry(),id);if(((Number)inst.get("submitted_by")).longValue()!=a.userId())throw new ApiException(403,"SYS_FORBIDDEN","只有提交人可以撤回");if(!Set.of("PENDING","BLOCKED").contains(inst.get("status")))throw state("只有审批中的单据可以撤回");skip(a,inst);finish(a,inst,"WITHDRAWN");decision(c,a,String.valueOf(inst.get("doc_type")),((Number)inst.get("doc_id")).longValue(),"WITHDRAWN");audit(a,"撤回审批",id,Map.of("status","WITHDRAWN"));return Map.of("id",id,"status","WITHDRAWN");});}
    private void prepareParticipant(RequestContext c,Access a,String type,long id){var p=participants.get(type);if(p!=null)p.prepare(c,a,id);}
    private void decision(RequestContext c,Access a,String type,long id,String status){var p=participants.get(type);if(p!=null)p.onDecision(c,a,id,status);}
    private Long insertRule(Access a,Map<String,Object>b,String key,int number,String status){return jdbc.queryForObject("INSERT INTO wf_rule(country_id,rule_key,doc_type,name,priority,conditions,nodes,version_no,status,effective_from,effective_to,created_by) VALUES(?,?,?,?,?,?::jsonb,?::jsonb,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),key,Inputs.required(b,"docType"),Inputs.required(b,"name"),b.getOrDefault("priority",100),json.write(b.getOrDefault("conditions",List.of())),json.write(normalizeNodes(b)),number,status,date(a,b.get("effectiveFrom"),jdbc.queryForObject("SELECT clock_timestamp()",(rs,n)->rs.getTimestamp(1).toInstant())),date(a,b.get("effectiveTo"),null),a.userId());}
    private void validateRule(Access a,Map<String,Object>b){Inputs.required(b,"name");Inputs.required(b,"docType");var nodes=normalizeNodes(b);if(nodes.isEmpty())throw Inputs.bad("至少需要一个审批节点");for(var node:nodes){if("USER".equals(node.get("approverType")))management.requireManageableUser(a,Inputs.id(node.get("approverRef")));else{var roles=jdbc.queryForList("SELECT id FROM sys_role WHERE country_id=? AND code=? AND status='ENABLED'",Long.class,a.requireCountry(),node.get("approverRef"));if(roles.isEmpty())throw Inputs.bad("审批角色不存在或已停用");management.requireManageableRole(a,roles.getFirst());}}for(var condition:listValue(b.getOrDefault("conditions",List.of()))){if(!(condition.get("field") instanceof String f)||f.isBlank()||condition.get("value")==null||!Set.of("gte","gt","lte","lt","eq").contains(String.valueOf(condition.get("op"))))throw Inputs.bad("审批条件不合法");}}
    private List<Map<String,Object>> normalizeNodes(Map<String,Object>b){var nodes=listValue(b.getOrDefault("nodes",List.of()));List<Map<String,Object>> out=new ArrayList<>();int seq=1;for(var node:nodes){String name=Inputs.required(node,"nodeName"),type=Inputs.required(node,"approverType"),mode=Inputs.text(node,"mode","ANY");if(!Set.of("USER","ROLE").contains(type)||!Set.of("ANY","ALL").contains(mode))throw Inputs.bad("审批节点不合法");Object ref=type.equals("USER")?Inputs.id(node.get("approverRef")):Inputs.required(node,"approverRef");out.add(Map.of("seq",seq++,"nodeName",name,"approverType",type,"approverRef",ref,"mode",mode));}return out;}
    private List<Long> approvers(Access a,Map<String,Object> node,String type,long id){List<Long> candidates="USER".equals(node.get("approverType"))?List.of(Inputs.id(node.get("approverRef"))):jdbc.queryForList("SELECT ur.user_id FROM sys_user_role ur JOIN sys_role r ON r.country_id=ur.country_id AND r.id=ur.role_id WHERE ur.country_id=? AND r.code=? AND r.status='ENABLED' ORDER BY ur.user_id",Long.class,a.requireCountry(),node.get("approverRef"));List<Long> eligible=new ArrayList<>();for(long user:new TreeSet<>(candidates))try{var subject=auth.accessForSubject(a,user);docs.requireDocumentAccess(subject,type,id,false);eligible.add(user);}catch(ApiException e){if(!Set.of(401,403,404).contains(e.getStatus()))throw e;}return eligible;}
    private Map<String,Object> snapshot(String type,Map<String,Object> source,Map<String,Object> cfg){Set<String> keys=new TreeSet<>(critical.get(type));if(cfg!=null)keys.addAll(SystemManagementService.strings(json.read(String.valueOf(cfg.get("key_fields")),List.class)));Map<String,Object> values=new TreeMap<>();for(String key:keys){if(!source.containsKey(key))throw new ApiException(400,"WF_CONFIG_MISSING","审批关键字段未在可信来源中提供");values.put(key,source.get(key));}return values;}
    private boolean snapshotMatches(Map<String,Object> inst,Map<String,Object> source){var stored=json.readMap(String.valueOf(inst.get("key_fields_snapshot")));if(!(stored.get("fields") instanceof Map<?,?> old))return false;Map<String,Object> current=new TreeMap<>();for(Object key:old.keySet()){String k=String.valueOf(key);if(!source.containsKey(k))return false;current.put(k,source.get(k));}return hash(current).equals(inst.get("key_fields_hash"));}
    private String hash(Map<String,Object> value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.write(canonical(value)).getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private Object canonical(Object value){if(value instanceof Map<?,?> map){Map<String,Object> out=new TreeMap<>();map.forEach((k,v)->out.put(String.valueOf(k),canonical(v)));return out;}if(value instanceof Collection<?> list)return list.stream().map(this::canonical).toList();if(value instanceof Number n)return new BigDecimal(n.toString()).stripTrailingZeros();if(value instanceof java.util.Date||value instanceof java.time.temporal.TemporalAccessor)return value.toString();return value;}
    private boolean matches(List<Map<String,Object>> conditions,Map<String,Object> facts){for(var c:conditions){Object value=facts.get(String.valueOf(c.get("field"))),expected=c.get("value");if(value==null||expected==null)return false;String op=String.valueOf(c.get("op"));if(op.equals("eq")){if(!Objects.equals(String.valueOf(value),String.valueOf(expected)))return false;}else{int n;try{n=new BigDecimal(value.toString()).compareTo(new BigDecimal(expected.toString()));}catch(NumberFormatException e){return false;}if(!switch(op){case "gte"->n>=0;case "gt"->n>0;case "lte"->n<=0;case "lt"->n<0;default->false;})return false;}}return true;}
    private Map<String,Object> config(Access a,String type){var cfg=jdbc.queryForList("SELECT * FROM wf_doc_type_config WHERE country_id=? AND doc_type=?",a.requireCountry(),type);return cfg.isEmpty()?null:cfg.getFirst();}
    private Map<String,Object> rule(Access a,long id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM wf_rule WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),id);if(rows.isEmpty())throw missing();return rows.getFirst();}
    private Map<String,Object> ruleOut(Map<String,Object> row){var out=camel(row);out.put("conditions",list(row.get("conditions")));out.put("nodes",list(row.get("nodes")));out.put("createdByName",jdbc.queryForObject("SELECT display_name FROM sys_user WHERE id=?",String.class,row.get("created_by")));return out;}
    private Map<String,Object> taskView(Access a,Map<String,Object> row){
        var out=camel(row);var saved=json.readMap(String.valueOf(row.get("key_fields_snapshot")));
        out.remove("keyFieldsSnapshot");out.remove("key_fields_snapshot");out.remove("keyFieldsHash");
        out.put("docNo",saved.getOrDefault("docNo",""));out.put("docTitle",saved.getOrDefault("docTitle",""));
        out.put("submittedByName",historyUser(a,row.get("submitted_by")));
        Map<?,?> facts=saved.get("facts") instanceof Map<?,?> m?m:Map.of(),snapshot=saved.get("fields") instanceof Map<?,?> m?m:Map.of();
        boolean allocation="COST_ALLOCATION".equals(row.get("doc_type"));
        Object currency=allocation?facts.get("baseCurrency"):facts.get("currency");if(!allocation&&(!(currency instanceof String text)||text.isBlank()))currency=snapshot.get("currency");
        out.put("currency",currency instanceof String text&&!text.isBlank()?text:null);
        String group=switch(String.valueOf(row.get("doc_type"))){
            case "PURCHASE_ORDER","PURCHASE_RETURN","AP_ADJUSTMENT","COST_ALLOCATION","COST_ADJUSTMENT"->"COST";
            case "SALES_ORDER","SALES_RETURN","REFUND"->"ORDER_TOTAL";
            default->null;
        };
        if(group!=null){Object amount=allocation?facts.get("baseAmount"):facts.get("amount");if(!allocation&&!(amount instanceof Number))amount=facts.get("totalAmount");if(!allocation&&!(amount instanceof Number))amount=snapshot.get("amount");if(amount instanceof Number)out.put("amount",amount);}
        return fields.mask(a,out,group==null?"ORDER_TOTAL":group);
    }
    private void createTasks(Access a,long instance,Map<String,Object> node,List<Long> users){for(long user:users)jdbc.update("INSERT INTO wf_task(country_id,instance_id,node_seq,node_name,assignee_id) VALUES(?,?,?,?,?)",a.requireCountry(),instance,node.get("seq"),node.get("nodeName"),user);}
    private void skip(Access a,Map<String,Object> inst){jdbc.update("UPDATE wf_task SET status='SKIPPED',version=version+1 WHERE country_id=? AND instance_id=? AND status='PENDING'",a.requireCountry(),inst.get("id"));}
    private void skipNode(Access a,Map<String,Object> inst,int seq){jdbc.update("UPDATE wf_task SET status='SKIPPED',version=version+1 WHERE country_id=? AND instance_id=? AND node_seq=? AND status='PENDING'",a.requireCountry(),inst.get("id"),seq);}
    private void finish(Access a,Map<String,Object> inst,String status){jdbc.update("UPDATE wf_instance SET status=?,finished_at=clock_timestamp(),version=version+1 WHERE country_id=? AND id=?",status,a.requireCountry(),inst.get("id"));}
    private void todo(Access a,String type,long id,String reason){jdbc.update("INSERT INTO sys_todo(country_id,todo_type,dedup_key,title,link,perm) VALUES(?,'CONFIG_MISSING',?,?,'/settings/approval-rules','wf:rule:edit') ON CONFLICT(country_id,dedup_key) DO UPDATE SET status='OPEN',title=EXCLUDED.title,resolved_at=NULL,version=sys_todo.version+1",a.requireCountry(),"WF_BLOCKED:"+type+":"+id,type+" #"+id+" 无法进入审批："+reason);}
    private void audit(Access a,String action,long id,Object after){auditWriter.append(a.requireCountry(),a.userId(),action,"approval",id,null,after,null);}

    @SuppressWarnings("unchecked") private List<Map<String,Object>> list(Object value){return listValue(json.read(String.valueOf(value),List.class));}
    private List<Map<String,Object>> listValue(Object value){if(!(value instanceof Collection<?> list))throw Inputs.bad("审批数组不合法");List<Map<String,Object>> out=new ArrayList<>();for(Object item:list){if(!(item instanceof Map<?,?> map))throw Inputs.bad("审批节点不合法");Map<String,Object> row=new LinkedHashMap<>();map.forEach((k,v)->row.put(String.valueOf(k),v));out.add(row);}return out;}
    private java.sql.Timestamp date(Access a,Object value,Instant fallback){if(value==null||value.toString().isBlank())return fallback==null?null:java.sql.Timestamp.from(fallback);try{String text=value.toString();if(text.length()==10){String zone=jdbc.queryForObject("SELECT timezone FROM sys_country WHERE id=?",String.class,a.requireCountry());return java.sql.Timestamp.from(LocalDate.parse(text).atStartOfDay(ZoneId.of(zone)).toInstant());}return java.sql.Timestamp.from(OffsetDateTime.parse(text).toInstant());}catch(Exception e){throw Inputs.bad("审批规则有效期不合法");}}
    private Map<String,Object> camel(Map<String,Object> row){Map<String,Object> out=new LinkedHashMap<>();row.forEach((key,v)->{StringBuilder b=new StringBuilder();boolean upper=false;for(char c:key.toCharArray()){if(c=='_')upper=true;else{b.append(upper?Character.toUpperCase(c):c);upper=false;}}out.put(b.toString(),v);});return out;}
    private Map<String,Object> page(List<Map<String,Object>> rows,Map<String,String> q){int page=pageInt(q.get("page"),1,1000000),size=pageInt(q.get("size"),20,200);String keyword=q.getOrDefault("keyword","").toLowerCase(Locale.ROOT);var filtered=rows.stream().filter(r->keyword.isEmpty()||String.valueOf(r.getOrDefault("name",r.getOrDefault("docTitle",""))).toLowerCase(Locale.ROOT).contains(keyword)).toList();int from=Math.min(filtered.size(),(page-1)*size);return Map.of("records",filtered.subList(from,Math.min(filtered.size(),from+size)),"total",filtered.size(),"page",page,"size",size);}
    private int pageInt(String value,int fallback,int max){if(value==null||value.isBlank())return fallback;try{int n=Integer.parseInt(value);if(n<1||n>max)throw Inputs.bad("分页参数不合法");return n;}catch(NumberFormatException e){throw Inputs.bad("分页参数不合法");}}
    private void requireCritical(String type){if(!critical.containsKey(type))throw missing();}
    private void requireTransaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Workflow API requires the calling transaction");}
    private static ApiException state(String message){return new ApiException(409,"SYS_STATE_INVALID",message);}
    private static ApiException invalidated(){return new ApiException(409,"WF_APPROVAL_INVALIDATED","单据关键字段已修改，需要重新提交审批");}
    private static ApiException missing(){return new ApiException(404,"NOT_FOUND","记录不存在或不在你的数据范围内");}
}
